    'info.an.tip': 'If you haven\'t used the chat yet you\'ll see \'—\': that\'s normal, there\'s no data yet.',
    'info.an.1h': 'Success rate',
    'info.an.1d': 'Percentage of requests that finished without error. The ring shows \'—\' if there are no requests yet.',
    'info.an.2h': 'Requests and p50/p95 latency',
    'info.an.2d': 'How many requests were made and how long they take: p50 is the median, p95 the slowest 5%.',
    'info.an.3h': 'Memory',
    'info.an.3d': 'How many memories Andromeda has and the hit rate when searching them in your conversations.',
    'info.an.4h': 'Tools (MCP)',
    'info.an.4d': 'External tool usage: how many times they were called, their latency and error rate.',
    'info.an.5h': 'Quality & SLO over time',
    'info.an.5d': 'Trend of success, latency and satisfaction. Green = within target (SLO), red = breaching. The arrow shows whether it\'s improving or degrading (drift).',
    'info.ab.intro': 'Compare two models in real use to see which is better, with statistical rigor.',
    'info.ab.tip': 'It won\'t declare a winner until there\'s enough sample and significance (p < 0.05): so you don\'t trust too few trials.',
    'info.ab.1h': 'Create an experiment',
    'info.ab.1d': 'Give it a name and pick two models (A and B) with a split weight. Requests are assigned to each one by that weight.',
    'info.ab.2h': 'Activate it',
    'info.ab.2d': 'Only the active experiment splits traffic. As you use it, each response counts toward A or B.',
    'info.ab.3h': 'Rate the quality',
    'info.ab.3d': 'With the 👍/👎 buttons on each response you feed each variant\'s satisfaction bar.',
    'info.ab.4h': 'Read the verdict',
    'info.ab.4d': 'You\'ll see a winner by success rate and another by quality, each with its p-value. If they tie, keep collecting data.',
    'info.reg.intro': 'Version your models and promote the best to production; the app will serve that version.',
    'info.reg.tip': 'Enable \'Serve production model\' so the chat automatically uses the promoted one (unless you force another model).',
    'info.reg.1h': 'Register a version',
    'info.reg.1d': 'Pick an Ollama model and save it as a version, optionally with a note. It starts in \'staging\'.',
    'info.reg.2h': 'Evaluate and compare',
    'info.reg.2d': 'Each version can carry an evaluation score (from the golden set) to decide which deserves production.',
    'info.reg.3h': 'Promote to production',
    'info.reg.3d': 'Only one version is in production at a time; promoting another archives the previous one automatically.',
    'info.reg.4h': 'Roll back if it degrades',
    'info.reg.4d': 'If satisfaction drops, archive the version and re-promote the previous one: one-click rollback.',
    'info.mdl.intro': 'Manage the local Ollama models Andromeda can use.',
    'info.mdl.tip': 'Plug-and-play: download a model in Ollama and it appears here automatically, ready to select.',
    'info.mdl.1h': 'Activate models',
    'info.mdl.1d': 'Mark which models the orchestrator can choose from based on your hardware.',
    'info.mdl.2h': 'Power levels',
    'info.mdl.2d': 'Each model maps to a level (LOW…ULTRA). In \'Auto\', Andromeda scales by your prompt and VRAM.',
    'info.mdl.3h': 'Available VRAM',
    'info.mdl.3d': 'A model that doesn\'t fit your VRAM appears disabled to avoid inference failures.',
    'info.mdl.4h': 'Download more',
    'info.mdl.4d': 'Use \'ollama pull <model>\' in your terminal; back here it\'ll show up available with no extra steps.',
    'info.mcp.intro': 'MCP tools give the AI extra capabilities: read files, git, web, etc.',
    'info.mcp.tip': 'Each server starts on demand; if one fails, the chat keeps working without it.',
    'info.mcp.1h': 'Enable a server',
    'info.mcp.1d': 'Turn on the MCP servers you want (e.g. filesystem or git). They need Node (npx) or uv.',
    'info.mcp.2h': 'The AI uses them itself',
    'info.mcp.2d': 'When a request needs it, the AI calls the tool and shows you the result in the chat.',
    'info.mcp.3h': 'Safe workspace',
    'info.mcp.3d': 'File tools act inside Andromeda\'s workspace folder, not your whole disk.',
    'info.mcp.4h': 'Check usage',
    'info.mcp.4d': 'In Analytics you can see how often each tool was called and its error rate.',
    'info.mem.intro': 'Andromeda remembers facts about you across conversations to personalize its answers.',
    'info.mem.tip': 'Everything is local and editable: you can delete any memory whenever you want.',
    'info.mem.1h': 'Memory profile',
    'info.mem.1d': 'An editable text block with what Andromeda knows about you. Edit it freely.',
    'info.mem.2h': 'Auto-generation',
    'info.mem.2d': 'If enabled, Andromeda extracts relevant facts from your chats and adds them to the profile.',
    'info.mem.3h': 'Conversation search',
    'info.mem.3d': 'Lets the AI search your past conversations to give context-aware answers.',
    'info.mem.4h': 'Full control',
    'info.mem.4d': 'Edit or clear the profile anytime; changes apply to the next responses.',
    'info.cap.intro': 'Enable or disable backend features that change what the AI can do.',
    'info.cap.tip': 'If something\'s slow or you don\'t want a feature (e.g. network), turn it off here.',
    'info.cap.1h': 'Memory and search',
    'info.cap.1d': 'Controls auto memory generation and search across past conversations.',
    'info.cap.2h': 'Visuals',
    'info.cap.2d': 'Enables artifacts (HTML/image preview) and inline visualizations in responses.',
    'info.cap.3h': 'Files and network',
    'info.cap.3d': 'Allows creating/editing files in the workspace and network egress (web search). Turn off for maximum privacy.',
    'info.cap.4h': 'Serve production',
    'info.cap.4d': 'If enabled, the chat serves the model promoted to production in the Model Registry.',
    'info.set.intro': 'Here you configure all of Andromeda: appearance, models, memory, tools and more.',
    'info.set.tip': 'Press Esc or Ctrl/Cmd+, to open and close this window quickly.',
    'info.set.1h': 'Navigate sections',
    'info.set.1d': 'The side menu groups settings by topic. Each section has its own (i) help button.',
    'info.set.2h': 'Appearance',
    'info.set.2d': 'Change theme, animated background (orbs, bands or waves) and incognito mode.',
    'info.set.3h': 'Models and memory',
    'info.set.3d': 'Define which models to use, what Andromeda remembers and which capabilities are active.',
    'info.set.4h': 'MLOps',
    'info.set.4d': 'A/B Testing and Model Registry let you compare models and promote the best to production.',

