    'info.an.intro': 'What each number on this screen means.',
    'info.an.tip': 'If you haven\'t used the chat yet you\'ll see \'—\': that\'s normal, there\'s no data yet.',
    'info.an.1h': 'Success rate',
    'info.an.1d': 'Percentage of requests that finished without error. The ring shows \'—\' if there are no requests yet.',
    'info.an.2h': 'Requests and p50/p95 latency',
    'info.an.2d': 'How many requests were made and how long they take: p50 is the median, p95 the slowest 5%.',
