    'info.an.5h': 'Quality & SLO over time',
    'info.an.5d': 'Trend of success, latency and satisfaction. Green = within target (SLO), red = breaching. The arrow shows whether it\'s improving or degrading (drift).',
    'info.ab.intro': 'Compare two models in real use to see which is better, with statistical rigor.',
    'info.ab.tip': 'It won\'t declare a winner until there\'s enough sample and significance (p < 0.05): so you don\'t trust too few trials.',
